insert into `ry_rental`.`ry_rental_merchant_oper_log`(
  tenant_id, member_id, operator_user_id, title, business_type, method, request_method,
  operator_type, oper_name, oper_url, oper_ip, oper_param, json_result, status,
  error_msg, oper_time, cost_time
) values (
  #{record.tenantId}, #{record.merchantId}, #{record.operatorUserId}, #{record.title},
  #{record.businessType}, #{record.method}, #{record.requestMethod}, #{record.operatorType},
  #{record.operName}, #{record.operUrl}, #{record.operIp}, #{record.operParam},
  #{record.jsonResult}, #{record.status}, #{record.errorMsg}, sysdate(), #{record.costTime}
)

mapper.select:
select 
from `ry_rental`.`ry_rental_merchant_oper_log`
where tenant_id = #{tenantId} and member_id = #{merchantId}

  and oper_ip like concat('%', #{query.operIp}, '%')


  and title like concat('%', #{query.title}, '%')


  and oper_name like concat('%', #{query.operName}, '%')

and business_type = #{query.businessType}
and status = #{query.status}

  and oper_time >= #{query.params.beginTime}


  and oper_time <= #{query.params.endTime}

order by oper_id desc
